from harvests import Harvest
from settle import is_settled


def test_tenths():
    assert is_settled([Harvest("a", 0.1), Harvest("b", 0.2)], 0.3)


def test_three_tenths():
    assert is_settled([Harvest("a", 0.1), Harvest("b", 0.1), Harvest("c", 0.1)], 0.3)


def test_not_settled():
    assert not is_settled([Harvest("a", 0.1), Harvest("b", 0.2)], 0.31)


def test_whole_numbers():
    assert is_settled([Harvest("a", 2), Harvest("b", 3)], 5) and not is_settled([Harvest("a", 2), Harvest("b", 3)], 6)


def test_nothing_owed():
    assert is_settled([], 0)

